={{
(() => {
  const c = $json.cliente || {};

  const limpio = (v) => (v ?? '').toString().trim();

  const telefono = limpio(c.telefono);
  const contacto = limpio(c.contacto);

  const correo = [...new Set(
    limpio(c.email)
      .split(',')
      .map(x => x.trim())
      .filter(Boolean)
  )].join(', ');

  const faltantes = [];

  if (!telefono) faltantes.push('Teléfono');
  if (!contacto) faltantes.push('Contacto');
  if (!correo) faltantes.push('Correo');

  let respuesta =
    "Información consultada directamente en CAF Web:\n\n" +
    "🔹 Cuenta: " + limpio(c.cuenta) + "\n" +
    "🔹 Cliente: " + limpio(c.nombre_cliente) + "\n" +
    "🔹 NIT: " + limpio(c.nit) + "\n" +
    "🔹 Dirección: " + limpio(c.direccion) + "\n" +
    "🔹 Ciudad: " + limpio(c.ciudad) + "\n" +
    "🔹 Teléfono: " + (telefono || "No registrado") + "\n" +
    "🔹 Contacto: " + (contacto || "No registrado") + "\n" +
    "🔹 Correo: " + (correo || "No registrado");

  if (faltantes.length > 0) {
    respuesta +=
      "\n\n⚠️ Información pendiente de completar:\n" +
      faltantes.map(campo => "• " + campo).join("\n");
  } else {
    respuesta +=
      "\n\n✅ El cliente tiene completos los datos principales de contacto en CAF Web.";
  }

  return respuesta;
})()
}}

